First, we note that the result is automatic if the line bundle $L$ is trivial. Let us therefore assume this is not the case, \textit{i.e.} that $\alpha$ is non-zero. The pseudo-Laplacian $\Delta_{L,0}$ is then the Chern Laplacian $\Delta_L$, as specified in definition \ref{DefPseudoLaplacian}. Since $\chi$ having finite order is equivalent to the rationality of $\alpha$, we have $n \alpha \in \mathbb{Z}$. In this proof, we identify any section of $L$ to a function $\psi : \mathbb{R} \times \left] a, + \infty \right[ \longrightarrow \mathbb{C}$ which satisfies $\psi \left( x+1, y \right) = e^{2 i \pi \alpha} \psi \left( x, y \right)$. Such a function is $n$-periodic in the first variable, and the map

\[ \begin{array}{cccllll}
        f & : & \mathcal{C}^{\infty} \left( S^1 \times \left] a, +\infty \right[, L \right) & \longrightarrow & \multicolumn{3}{l}{\mathcal{C}^{\infty} \left( S^1 \times \left] \frac{a}{n}, +\infty \right[ \right)} \\[0.5em]

        && \psi & \longmapsto & \left( x, y \right) & \longmapsto & \psi \left( nx, ny \right)
    \end{array} \]

\noindent is an injection from the space of smooth sections of $L$ into the space of smooth functions (\textit{i.e.} smooth sections of the trivial line bundle), which commutes with the Chern Laplacians. For any smooth section $\psi$ of $L$, and any $y > a/n$, we have

\[ \begin{array}{lllllll}
        \scriptstyle \int_0^1 \; f \left( \psi \right) \left( x, y \right) \; \mathrm{d}x & \scriptstyle = & \scriptstyle \int_0^1 \; \psi \left( nx, ny \right) \; \mathrm{d}x & \scriptstyle = & \scriptstyle \frac{1}{n} \sum\limits_{j=0}^{n-1} \left( e^{2i\pi \alpha} \right)^j \int_0^1 \; \psi \left( x, ny \right) \; \mathrm{d}x & \scriptstyle = & \scriptstyle 0,
    \end{array} \]

\noindent Thus $f$ takes values in the space of smooth sections with vanishing constant Fourier coefficient. Now, we have

\[ \begin{array}{lll}
        \scriptstyle \int_{a/n}^{+ \infty} \; \int_0^1 \; \left( \Delta f \left( \psi \right) \right) \left( x, y \right) \overline{f \left( \psi \right) \left( x, y \right)} \; \frac{\mathrm{d}x \, \mathrm{d}y}{y^2} & \scriptstyle = & \scriptstyle \int_{a/n}^{+ \infty} \; \int_0^1 \; \left( \Delta_L \psi \right) \left( nx, ny \right) \overline{\psi \left( nx, ny \right)} \; \frac{\mathrm{d}x \, \mathrm{d}y}{y^2} \\[0.8em]

        & = & \scriptstyle n \int_{a}^{+ \infty} \; \int_0^1 \; \left( \Delta_L \psi \right) \left( x, y \right) \overline{\psi \left( x, y \right)} \; \frac{\mathrm{d}x \, \mathrm{d}y}{y^2}.
    \end{array} \]

\noindent Similarly, we have

\[ \begin{array}{lll}
        \int_{a/n}^{+ \infty} \; \int_0^1 \; f \left( \psi \right) \left( x, y \right) \overline{f \left( \psi \right) \left( x, y \right)} \; \frac{\mathrm{d}x \, \mathrm{d}y}{y^2} & = & n \int_{a}^{+ \infty} \; \int_0^1 \; \psi \left( x, y \right) \overline{\psi \left( x, y \right)} \; \frac{\mathrm{d}x \, \mathrm{d}y}{y^2}.
    \end{array} \]

\noindent Taking the quotient of these two integrals, assuming $\psi$ is non-zero, we get

\begin{equation}
\label{EqRayleighQuotient}
    \begin{array}{lll}
        \frac{\overline{Q_{\Delta}} \left( f \left( \psi \right), f \left( \psi \right) \right)}{\left< f \left( \psi \right), f \left( \psi \right) \right>} & = & \frac{\overline{Q_{\Delta_L}} \left( \psi, \psi \right)}{\left< \psi, \psi \right>}.
    \end{array}
\end{equation}

\noindent The map $f$ then extends into

\[ \begin{array}{lllll}
        f & : & L^2_{1,\mathrm{Dir}} \left( \mathbb{R} \times \left] a, + \infty \right[, L \right) & \longrightarrow & L^2_{1,\mathrm{Dir}} \left( \mathbb{R} \times \left] a, + \infty \right[ \right)_0
    \end{array} , \]

\noindent Furthermore, equality \eqref{EqRayleighQuotient} remains valid for this continuation. This allows us to compare the spectral quantities $\mu_n$ and $\mu_n \left( \Delta_L \right)$, as we have

\[ \begin{array}{lll}
