        \qquad \qquad \qquad \qquad & \leqslant & \inf\limits_{\psi_1, \dots, \psi_k} \sup \left \{ \frac{\overline{Q_{\Delta_L}} \left( \psi, \psi \right)}{\left< \psi, \psi \right>}, \; \psi \in \mathrm{span} \left( \psi_1, \dots, \psi_k \right), \; \psi \neq 0 \right \}.
    \end{array} \]

