        \frac{\Gamma \left( \mu \right) \Gamma \left( \nu - \mu \right)}{\Gamma \left( \nu \right)} & = & \int_0^1 t^{\mu - 1} \left( 1 - t \right)^{\nu - \mu - 1} \mathrm{d}t & = & \int_0^{+ \infty} \frac{y^{\mu - 1}}{\left( 1 + y \right)^{\nu}} \mathrm{d}t
    \end{array}
\end{equation}

\noindent using the change of variable $t = y/\left( y+1 \right)$. Using proposition \ref{PropEulerIntegralFormula}, we have

\[ \begin{array}{lll}
        F \left( \nu, \nu - \mu; \nu - \mu + 1; z \right) & = & \frac{\Gamma \left( \nu - \mu + 1 \right)}{\Gamma \left( \nu - \mu \right)} \int_0^1 \; t^{\nu - \mu -1} \left( 1 + \frac{t}{u} \right)^{- \nu} \; \mathrm{d}t \\[1em]

        & = & \left( \nu - \mu \right) u^{\nu - \mu} \int_0^{1/u} x^{\nu - \mu - 1} \left( 1 + x \right)^{-\nu} \mathrm{d}x
